from typing import Dict, Iterable, List, Mapping
from stockflow.parse_movement_line import parse_movement_line

def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    if idle_days < 1:
        raise ValueError("idle_days must be at least 1")
    on_hand, last_ship, first_arr = {}, {}, {}
    for line in lines:
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        m = parse_movement_line(text, case_sizes)
        if m["day"] > today:
            continue
        sku, day, qty, m_type = m["sku"], m["day"], m["qty"], m["type"]
        on_hand[sku] = on_hand.get(sku, 0) + qty
        if m_type == "SHP":
            last_ship[sku] = max(last_ship.get(sku, -1), day)
        if m_type in ("RCV", "RTN"):
            first_arr[sku] = min(first_arr.get(sku, float('inf')), day)
    dead = []
    for sku, qty in on_hand.items():
        if qty > 0:
            day = last_ship.get(sku, first_arr.get(sku, float('inf')))
            if today - day >= idle_days:
                dead.append(sku)
    return sorted(dead)"
